def prime_factorization(n):
    """Returns a dictionary of prime factors and their exponents for n."""
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_n_to_the_12(n):
    """Calculates tau(n^12), the number of divisors of n^12."""
    if n == 1:
        return 1 # tau(1^12) = tau(1) = 1

    factors = prime_factorization(n)

    tau_val = 1
    for exponent in factors.values():
        # If n = p^a, n^12 = p^(12a). tau(n^12) = 12a + 1
        tau_val *= (12 * exponent + 1)
    return tau_val

solutions = []
for n in range(1, 1001):
    tau_val = tau_n_to_the_12(n)
    if n == tau_val:
        solutions.append(n)

print("Solutions found (n <= 1000):", solutions)

# Analyze patterns for solutions found
print("\nAnalysis of solutions:")
if not solutions:
    print("No solutions found in the range.")
else:
    for n in solutions:
        factors = prime_factorization(n)
        print(f"n={n}: Prime factorization = {factors}")

